use crate::frp::config::FrpClientConfig;
use serde::Serialize;

/// Renders FrpClientConfig to TOML string (FRP client config format)
pub struct FrpConfigRenderer;

impl FrpConfigRenderer {
    pub fn render(config: &FrpClientConfig) -> Result<String, toml::ser::Error> {
        toml::to_string_pretty(config)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::frp::config::{FrpClientAuthConfig, FrpClientAuthMethod};

    #[test]
    fn test_render_client_config() {
        let config = FrpClientConfig {
            server_address: "frps.example.com".to_string(),
            server_port: 7000,
            auth: FrpClientAuthConfig {
                method: FrpClientAuthMethod::Token,
                token: "test-token".to_string(),
            },
        };

        let rendered = FrpConfigRenderer::render(&config).expect("render failed");
        println!("{}", rendered);
        assert!(rendered.contains("serverAddr"));
        assert!(rendered.contains("frps.example.com"));
    }
}

use k8s_openapi::api::apps::v1::{Deployment, DeploymentSpec};
use k8s_openapi::api::core::v1::{
    Container, PodSpec, PodTemplateSpec, Volume, VolumeMount,
    SecretVolumeSource,
};
use k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, LabelSelector, OwnerReference};

/// Generates a Deployment running the FRP client (frpc) with the config Secret
pub struct FrpClientDeploymentBuilder;

impl FrpClientDeploymentBuilder {
    /// Build a Deployment resource for running FRPC
    ///
    /// # Arguments
    /// * `namespace` - Target namespace
    /// * `client_name` - Name of the Client resource (used for naming)
    /// * `frpc_image` - Container image for FRPC (e.g., "ghcr.io/fatedier/frp:v0.47.0")
    /// * `config_secret_name` - Name of the Secret holding frpc.toml
    /// * `owner_ref` - Optional owner reference for garbage collection
    pub fn build(
        namespace: &str,
        client_name: &str,
        frpc_image: &str,
        config_secret_name: &str,
        owner_ref: Option<OwnerReference>,
    ) -> Deployment {
        let labels = {
            let mut map = std::collections::BTreeMap::new();
            map.insert("app.kubernetes.io/name".to_string(), "frp-client".to_string());
            map.insert("app.kubernetes.io/instance".to_string(), client_name.to_string());
            map.insert(
                "app.kubernetes.io/managed-by".to_string(),
                "frp-operator".to_string(),
            );
            map
        };

        let config_volume = Volume {
            name: "frpc-config".to_string(),
            secret: Some(SecretVolumeSource {
                secret_name: Some(config_secret_name.to_string()),
                default_mode: Some(0o400),
                ..Default::default()
            }),
            ..Default::default()
        };

        let config_mount = VolumeMount {
            name: "frpc-config".to_string(),
            mount_path: "/etc/frp".to_string(),
            read_only: Some(true),
            ..Default::default()
        };

        let frpc_container = Container {
            name: "frpc".to_string(),
            image: Some(frpc_image.to_string()),
            image_pull_policy: Some("IfNotPresent".to_string()),
            args: Some(vec!["-c".to_string(), "/etc/frp/frpc.toml".to_string()]),
            volume_mounts: Some(vec![config_mount]),
            ..Default::default()
        };

        let pod_spec = PodSpec {
            containers: vec![frpc_container],
            volumes: Some(vec![config_volume]),
            restart_policy: Some("Always".to_string()),
            termination_grace_period_seconds: Some(10),
            ..Default::default()
        };

        let pod_template = PodTemplateSpec {
            metadata: Some(ObjectMeta {
                labels: Some(labels.clone()),
                ..Default::default()
            }),
            spec: Some(pod_spec),
        };

        let mut deploy_meta = ObjectMeta {
            name: Some(format!("{}-deployment", client_name)),
            namespace: Some(namespace.to_string()),
            labels: Some(labels),
            ..Default::default()
        };

        if let Some(owner) = owner_ref {
            deploy_meta.owner_references = Some(vec![owner]);
        }

        let spec = DeploymentSpec {
            replicas: Some(1),
            selector: LabelSelector {
                match_labels: {
                    let mut selector = std::collections::BTreeMap::new();
                    selector.insert("app.kubernetes.io/instance".to_string(), client_name.to_string());
                    Some(selector)
                },
                ..Default::default()
            },
            template: pod_template,
            ..Default::default()
        };

        Deployment {
            metadata: deploy_meta,
            spec: Some(spec),
            status: None,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_build_deployment() {
        let deploy = FrpClientDeploymentBuilder::build(
            "default",
            "my-frp-client",
            "ghcr.io/fatedier/frp:v0.47.0",
            "my-frp-client-config",
            None,
        );

        assert_eq!(
            deploy.metadata.name,
            Some("my-frp-client-deployment".to_string())
        );
        assert_eq!(deploy.metadata.namespace, Some("default".to_string()));

        let spec = deploy.spec.unwrap();
        assert_eq!(spec.replicas, Some(1));
        assert_eq!(spec.template.spec.as_ref().unwrap().containers.len(), 1);

        let container = &spec.template.spec.unwrap().containers[0];
        assert_eq!(container.name, "frpc");
        assert_eq!(container.image, Some("ghcr.io/fatedier/frp:v0.47.0".to_string()));
    }
}

use k8s_openapi::api::core::v1::Secret;
use k8s_openapi::apimachinery::pkg::apis::meta::v1::{ObjectMeta, OwnerReference};
use k8s_openapi::ByteString;
use crate::frp::config::renderer::FrpConfigRenderer;
use crate::frp::config::FrpClientConfig;

/// Generates a Secret containing the rendered FRP client config
pub struct FrpConfigSecretBuilder;

impl FrpConfigSecretBuilder {
    /// Build a Secret resource holding the rendered FRPC config
    pub fn build(
        config: &FrpClientConfig,
        namespace: &str,
        config_name: &str,
        owner_ref: Option<OwnerReference>,
    ) -> Result<Secret, Box<dyn std::error::Error>> {
        let rendered_config = FrpConfigRenderer::render(config)?;

        let mut data = std::collections::BTreeMap::new();
        data.insert(
            "frpc.toml".to_string(),
            ByteString(rendered_config.into_bytes()),
        );

        let mut meta = ObjectMeta {
            name: Some(format!("{}-config", config_name)),
            namespace: Some(namespace.to_string()),
            ..Default::default()
        };

        if let Some(owner) = owner_ref {
            meta.owner_references = Some(vec![owner]);
        }

        Ok(Secret {
            metadata: meta,
            data: Some(data),
            type_: Some("Opaque".to_string()),
            ..Default::default()
        })
    }
}
